def sh(*args):
    subprocess.run(args,check=True)

for key,meta in SOURCES.items():
    dst=SRC/f'{key}.jpg'
    if not dst.exists():
        sh('curl','-L','--fail','--retry','4','--retry-delay','2','-A','ManzanitaWorks/1.7 visual-recovery',meta['url'],'-o',str(dst))
    im=Image.open(dst); im.verify()

def twin(src:Path,dst:Path):
    im=Image.open(src).convert('RGB')
    im=ImageOps.autocontrast(im,cutoff=0.4)
    im=ImageEnhance.Contrast(im).enhance(0.96)
    im=ImageEnhance.Color(im).enhance(0.90)
    im=ImageEnhance.Brightness(im).enhance(1.015)
    im.save(dst,'WEBP',quality=91,method=6)

for key in SOURCES:
    twin(SRC/f'{key}.jpg',AS/f'{key}-twin.webp')

lida=Image.open(AS/'lida-twin.webp').convert('RGB')
w,h=lida.size
plant=lida.crop((int(w*.47),int(h*.48),int(w*.88),int(h*.94)))
plant=ImageOps.fit(plant,(1200,900),Image.Resampling.LANCZOS)
plant.save(AS/'plant-detail.webp','WEBP',quality=91,method=6)

ims=[Image.open(AS/f'michigan0{i}-twin.webp').convert('RGB') for i in range(1,5)]
region=Image.new('RGB',(1600,1200),'#11150f')
for idx,im in enumerate(ims):
    tile=ImageOps.fit(im,(790,590),Image.Resampling.LANCZOS)
    x=0 if idx%2==0 else 810; y=0 if idx<2 else 610
    region.paste(tile,(x,y))
d=ImageDraw.Draw(region,'RGBA')
d.line((800,0,800,1200),fill=(238,233,218,220),width=7)
d.line((0,600,1600,600),fill=(238,233,218,220),width=7)
d.rectangle((28,28,1572,1172),outline=(255,91,50,230),width=5)
for x,y in [(280,255),(1060,320),(520,830),(1290,875)]:
    d.ellipse((x-12,y-12,x+12,y+12),fill=(255,91,50,235),outline=(245,241,229,240),width=3)
d.line([(280,255),(1060,320),(1290,875),(520,830)],fill=(255,91,50,190),width=5)
region.save(AS/'region-context.webp','WEBP',quality=90,method=6)

stew=Image.new('RGB',(1600,1200),'#10130f')
allkeys=['lida','michigan01','michigan02','michigan04']
for idx,key in enumerate(allkeys):
    im=Image.open(AS/f'{key}-twin.webp').convert('RGB')
    tile=ImageOps.fit(im,(790,590),Image.Resampling.LANCZOS)
    x=0 if idx%2==0 else 810; y=0 if idx<2 else 610
    stew.paste(tile,(x,y))
d=ImageDraw.Draw(stew,'RGBA')
d.line((800,0,800,1200),fill=(245,241,229,225),width=8)
d.line((0,600,1600,600),fill=(245,241,229,225),width=8)
d.rectangle((24,24,1576,1176),outline=(86,140,91,230),width=5)
for n,(x,y) in enumerate([(45,45),(855,45),(45,655),(855,655)],1):
    d.rounded_rectangle((x,y,x+100,y+54),radius=10,fill=(14,18,14,220),outline=(245,241,229,210),width=2)
    d.text((x+29,y+17),f'{n:02d}',fill=(255,91,50,255))
stew.save(AS/'stewardship-board.webp','WEBP',quality=90,method=6)

